import React, { useState, useEffect } from 'react';
import PostList from './PostList';

const ProfilePost = ({ user }) => {
  const [userPosts, setUserPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [currentPage, setCurrentPage] = useState(1);
  const postsPerPage = 5;

  useEffect(() => {
    const fetchUserPosts = async () => {
      try {
        const res = await fetch('http://localhost/coolpage/my-app/backend/get_posts.php');
        const data = await res.json();

        if (data.success) {
          const filtered = data.posts.filter(post => Number(post.user_id) === Number(user.id));
          setUserPosts(filtered);
        } else {
          console.error('⚠️ Failed to load posts:', data.message);
        }
      } catch (err) {
        console.error('❌ Error fetching posts:', err.message);
      } finally {
        setLoading(false);
      }
    };

    if (user?.id) {
      fetchUserPosts();
    }
  }, [user]);

  if (!user) return <p style={{ textAlign: 'center' }}>Please log in to view your profile posts.</p>;

  // 🔢 Pagination
  const totalPages = Math.ceil(userPosts.length / postsPerPage);
  const startIndex = (currentPage - 1) * postsPerPage;
  const currentPosts = userPosts.slice(startIndex, startIndex + postsPerPage);

  const handlePageChange = (newPage) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
    }
  };

  return (
    <div>
      <h2 style={{ textAlign: 'center', marginTop: '20px' }}>
        {user.username || user.email}'s Posts
      </h2>

      {loading ? (
        <p style={{ textAlign: 'center' }}>Loading your posts...</p>
      ) : (
        <>
          <PostList
            posts={currentPosts}
            user={user}
            onReply={() => {}}
            onRefresh={() => {
              // Optional re-fetch logic for refreshing posts
              setLoading(true);
              setTimeout(() => {
                fetch(`http://localhost/coolpage/my-app/backend/get_posts.php`)
                  .then(res => res.json())
                  .then(data => {
                    const filtered = data.posts.filter(post => Number(post.user_id) === Number(user.id));
                    setUserPosts(filtered);
                  })
                  .finally(() => setLoading(false));
              }, 300);
            }}
          />

          {/* 🔀 Pagination Controls */}
          {totalPages > 1 && (
            <div style={{ display: 'flex', justifyContent: 'center', marginTop: '20px', gap: '10px' }}>
              <button
                disabled={currentPage === 1}
                onClick={() => handlePageChange(currentPage - 1)}
              >
                &laquo; Prev
              </button>
              <span>Page {currentPage} of {totalPages}</span>
              <button
                disabled={currentPage === totalPages}
                onClick={() => handlePageChange(currentPage + 1)}
              >
                Next &raquo;
              </button>
            </div>
          )}
        </>
      )}
    </div>
  );
};

export default ProfilePost;
