import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';

const Login = ({ onLogin }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const res = await fetch('http://localhost/coolpage/my-app/backend/login.php', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: new URLSearchParams({ email, password }).toString(),
      });

      const data = await res.json();

      if (data.success && data.user) {
        const user = data.user;

        if (!user.id || !user.email || !user.role) {
          alert('Invalid user data received. Please try again.');
          return;
        }

        localStorage.setItem('forumUser', JSON.stringify(user));
        localStorage.setItem('userEmail', user.email);

        if (user.role === 'admin') {
          window.location.href = '/admin';
        } else {
          onLogin(user);
        }
      } else {
        alert(data.message || 'Login failed');
      }
    } catch (error) {
      console.error('Login error:', error);
      alert('Error: ' + error.message);
    }
  };

  const onShowRegister = () => {
    navigate('/register');
  };

  return (
    <div style={{
      maxWidth: 500,
      margin: '50px auto',
      padding: '40px 30px',
      background: '#e6f2ff',
      boxShadow: '0 8px 16px rgba(0, 123, 255, 0.15)',
      borderRadius: 16,
      border: '1px solid #b3d7ff',
    }}>
      <h2 style={{ textAlign: 'center', marginBottom: 25, color: '#0056b3' }}>Login</h2>
      <form onSubmit={handleSubmit}>
        <div style={{ marginBottom: 18 }}>
          <label style={{ display: 'block', marginBottom: 6, color: '#003d80' }}>Email</label>
          <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
            style={{
              width: '100%',
              padding: 12,
              border: '1px solid #99c2ff',
              borderRadius: 6,
              outline: 'none',
              background: '#fff'
            }}
          />
        </div>
        <div style={{ marginBottom: 25 }}>
          <label style={{ display: 'block', marginBottom: 6, color: '#003d80' }}>Password</label>
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            style={{
              width: '100%',
              padding: 12,
              border: '1px solid #99c2ff',
              borderRadius: 6,
              outline: 'none',
              background: '#fff'
            }}
          />
        </div>
        <button
          type="submit"
          style={{
            width: '100%',
            padding: 14,
            background: '#007bff',
            color: '#fff',
            fontWeight: 'bold',
            border: 'none',
            borderRadius: 8,
            cursor: 'pointer'
          }}
        >
          Login
        </button>
      </form>

      <p style={{ textAlign: 'center', marginTop: 20, color: '#003d80' }}>
        Don’t have an account?{' '}
        <button
          onClick={onShowRegister}
          style={{
            background: 'none',
            border: 'none',
            color: '#007bff',
            cursor: 'pointer',
            textDecoration: 'underline',
            fontWeight: 'bold'
          }}
        >
          Register here
        </button>
      </p>

      <p style={{ textAlign: 'center', marginTop: 10, color: '#003d80' }}>
        Or{' '}
        <Link to="/" style={{ color: '#007bff', fontWeight: 'bold' }}>
          Visit the forum without login
        </Link>
      </p>
    </div>
  );
};

export default Login;
